#include "native_time_platform.h"
#include "pinned.inc"
#include "backend.inc"

static unsigned callbacks;
static void on_sync(void *ctx,const struct timeval *tv){assert(ctx==&callbacks&&tv);callbacks++;}
static native_time_sntp_config_t config(unsigned count,unsigned version){native_time_sntp_config_t c={.sync_interval_minutes=(uint16_t)(60+version),.server_count=(uint8_t)count};snprintf(c.servers[0],35,"first-%u.example",version);snprintf(c.servers[1],35,"second-%u.example",version);return c;}
static void ready(void){assert(native_time_sntp_init(on_sync,&callbacks)==ESP_OK);native_time_sntp_notify_network_ready();}
static void core_begin(void){assert(!in_tcpip);assert(!pthread_mutex_lock(&tcpip_lock));in_tcpip=true;}
static void core_end(void){assert(in_tcpip);in_tcpip=false;assert(!pthread_mutex_unlock(&tcpip_lock));}
static void cleanup(void){core_begin();sntp_stop();core_end();if(s_storage){free(s_storage);s_storage=NULL;}cleanup_sems();assert(udp_created==udp_removed);}
static void run_request(void){core_begin();sntp_request(NULL);core_end();}
static unsigned pending_dns(void){unsigned n=0;for(unsigned i=0;i<DNS_TABLE_SIZE;i++)n+=dns_requests[i].found!=NULL;return n;}
static unsigned find_dns(const char *name){for(unsigned i=0;i<DNS_TABLE_SIZE;i++)if(dns_requests[i].found&&!strcmp(dns_table[i].name,name))return i;assert(!"DNS entry absent");return 0;}
static void complete_dns(unsigned index,bool success,unsigned ip){assert(index<DNS_TABLE_SIZE&&dns_requests[index].found);dns_found_callback callback=dns_requests[index].found;void *arg=dns_requests[index].arg;dns_requests[index].found=NULL;dns_table[index].state=DNS_STATE_DONE;ip_addr_t address={ip};core_begin();callback(dns_table[index].name,success?&address:NULL,arg);core_end();}
static void *apply_thread(void *p){assert(native_time_sntp_apply(p)==ESP_OK);return NULL;}

int main(int argc,char **argv){assert(argc==2);const char *test=argv[1];native_time_sntp_config_t a=config(1,1),b=config(1,2),c=config(1,3);
 if(!strcmp(test,"readiness")){assert(native_time_sntp_apply(&a)==ESP_ERR_INVALID_STATE);assert(native_time_sntp_restart()==ESP_ERR_INVALID_STATE);assert(!ipc_calls);assert(native_time_sntp_init(on_sync,&callbacks)==ESP_OK);assert(!ipc_calls);assert(native_time_sntp_apply(&a)==ESP_ERR_INVALID_STATE);native_time_sntp_notify_network_ready();assert(native_time_sntp_apply(&a)==ESP_OK);}
 else if(!strcmp(test,"init")){ready();assert(native_time_sntp_init(on_sync,&callbacks)==ESP_OK);assert(native_time_sntp_init(NULL,NULL)==ESP_ERR_INVALID_STATE);assert(!ipc_calls);assert(native_time_sntp_restart()==ESP_ERR_INVALID_STATE);}
 else if(!strcmp(test,"mutex_oom")){fail_allocation=1;assert(native_time_sntp_init(on_sync,&callbacks)==ESP_ERR_NO_MEM);assert(!ipc_calls);fail_allocation=0;ready();assert(native_time_sntp_apply(&a)==ESP_OK);}
 else if(!strcmp(test,"lock_timeout")){ready();forced_timeout=atomic_load(&s_lock);assert(native_time_sntp_apply(&a)==ESP_ERR_TIMEOUT);assert(native_time_sntp_restart()==ESP_ERR_TIMEOUT);assert(!ipc_calls);forced_timeout=NULL;}
 else if(!strcmp(test,"validation")){ready();assert(native_time_sntp_apply(NULL)==ESP_ERR_INVALID_ARG);native_time_sntp_config_t bad=a;bad.server_count=0;assert(native_time_sntp_apply(&bad)==ESP_ERR_INVALID_ARG);bad=a;bad.server_count=3;assert(native_time_sntp_apply(&bad)==ESP_ERR_INVALID_ARG);bad=a;bad.sync_interval_minutes=14;assert(native_time_sntp_apply(&bad)==ESP_ERR_INVALID_ARG);bad.sync_interval_minutes=1441;assert(native_time_sntp_apply(&bad)==ESP_ERR_INVALID_ARG);bad=a;memset(bad.servers[0],'x',35);assert(native_time_sntp_apply(&bad)==ESP_ERR_INVALID_ARG);const char *names[]={"","bad name","bad\rname","a/b","a\\b","a\"b"};for(unsigned i=0;i<sizeof(names)/sizeof(*names);i++){bad=a;snprintf(bad.servers[0],35,"%s",names[i]);assert(native_time_sntp_apply(&bad)==ESP_ERR_INVALID_ARG);}assert(!ipc_calls);}
 else if(!strcmp(test,"capacity")){ready();native_time_sntp_config_t two=config(2,1);assert(native_time_sntp_apply(&two)==(SNTP_MAX_SERVERS<2?ESP_ERR_INVALID_ARG:ESP_OK));if(SNTP_MAX_SERVERS<2)assert(!ipc_calls);}
 else if(!strcmp(test,"immutable")){ready();assert(native_time_sntp_apply(&a)==ESP_OK);const char *borrowed=sntp_getservername(0);assert(borrowed!=a.servers[0]);char old[35];strcpy(old,borrowed);memset(a.servers,'z',sizeof(a.servers));assert(!strcmp(borrowed,old));run_request();unsigned entry=find_dns(old);assert(native_time_sntp_apply(&b)==ESP_OK);assert(!strcmp(dns_table[entry].name,old));assert(native_time_sntp_apply(&c)==ESP_OK);assert(!strcmp(dns_table[entry].name,old));assert(!strcmp(sntp_getservername(0),c.servers[0]));}
 else if(!strcmp(test,"equal_no_restart")){ready();assert(native_time_sntp_apply(&a)==ESP_OK);unsigned count=udp_created;core_begin();sntp_retry(NULL);core_end();unsigned timers_before=timer_count();assert(native_time_sntp_apply(&a)==ESP_OK);assert(udp_created==count&&timer_count()==timers_before);assert(native_time_sntp_restart()==ESP_OK);assert(udp_created==count+1);}
 else if(!strcmp(test,"all_slots")){ready();native_time_sntp_config_t two=config(2,1);assert(SNTP_MAX_SERVERS>=2);assert(native_time_sntp_apply(&two)==ESP_OK);core_begin();sntp_servers[1].addr.addr=0x12345678;core_end();assert(native_time_sntp_apply(&b)==ESP_OK);assert(sntp_getservername(1)==NULL&&sntp_getserver(1)->addr==0);assert(native_time_sntp_apply(&c)==ESP_OK);assert(sntp_getservername(1)==NULL&&sntp_getserver(1)->addr==0);}
 else if(!strcmp(test,"all_bank_refs")){ready();assert(SNTP_MAX_SERVERS>=2);assert(native_time_sntp_apply(&a)==ESP_OK);const char *old=sntp_getservername(0);char saved[35];strcpy(saved,old);assert(native_time_sntp_apply(&b)==ESP_OK);core_begin();sntp_setservername(1,old);core_end();unsigned count=udp_created;assert(native_time_sntp_apply(&c)==ESP_ERR_INVALID_STATE);assert(udp_created==count&&!strcmp(old,saved));}
 else if(!strcmp(test,"late_dns")){ready();assert(native_time_sntp_apply(&a)==ESP_OK);run_request();unsigned entry=find_dns(a.servers[0]);assert(pending_dns());unsigned first_pcb=udp_created;assert(native_time_sntp_apply(&b)==ESP_OK);assert(native_time_sntp_apply(&c)==ESP_OK);assert(udp_created==first_pcb+2);unsigned before=sent;complete_dns(entry,true,0x76543210);assert(sent==before+1&&last_sent.addr==0x76543210);assert(!strcmp(sntp_getservername(0),c.servers[0]));puts("KNOWN SDK limitation: old DNS result uses current PCB; no generation cancellation");}
 else if(!strcmp(test,"late_dns_failure")){ready();assert(native_time_sntp_apply(&a)==ESP_OK);run_request();unsigned entry=find_dns(a.servers[0]);assert(native_time_sntp_apply(&b)==ESP_OK);complete_dns(entry,false,0);assert(timer_count()>0);assert(!strcmp(sntp_getservername(0),b.servers[0]));}
 else if(!strcmp(test,"managed_oom")){ready();fail_allocation=allocations+1;assert(native_time_sntp_apply(&a)==ESP_ERR_NO_MEM);assert(!s_managed&&!s_storage&&!sntp_enabled()&&!sntp_getservername(0));fail_allocation=0;assert(native_time_sntp_apply(&b)==ESP_OK);}
 else if(!strcmp(test,"managed_ipc")){ready();fail_ipc_at=2;assert(native_time_sntp_apply(&a)==ESP_FAIL);assert(!s_managed&&!s_storage&&!sntp_enabled()&&!sntp_getservername(0));fail_ipc_at=0;assert(native_time_sntp_apply(&b)==ESP_OK);}
 else if(!strcmp(test,"apply_ipc")){ready();assert(native_time_sntp_apply(&a)==ESP_OK);const char *old=sntp_getservername(0);unsigned count=udp_created;fail_ipc_at=ipc_calls+1;assert(native_time_sntp_apply(&b)==ESP_FAIL);assert(sntp_getservername(0)==old&&!strcmp(old,a.servers[0])&&udp_created==count);fail_ipc_at=0;assert(native_time_sntp_apply(&c)==ESP_OK);}
 else if(!strcmp(test,"foreign_client")){ready();core_begin();sntp_setservername(0,"foreign.example");core_end();assert(native_time_sntp_apply(&a)==ESP_ERR_INVALID_STATE);assert(!strcmp(sntp_getservername(0),"foreign.example")&&!s_managed);}
 else if(!strcmp(test,"concurrent")){ready();assert(native_time_sntp_apply(&a)==ESP_OK);pthread_t t1,t2;assert(!pthread_create(&t1,NULL,apply_thread,&b));assert(!pthread_create(&t2,NULL,apply_thread,&c));assert(!pthread_join(t1,NULL)&&!pthread_join(t2,NULL));assert(udp_created==3&&udp_removed==2);assert(!strcmp(sntp_getservername(0),b.servers[0])||!strcmp(sntp_getservername(0),c.servers[0]));}
 else if(!strcmp(test,"sync_packet")){ready();assert(native_time_sntp_apply(&a)==ESP_OK);core_begin();struct pbuf *p=pbuf_alloc(PBUF_TRANSPORT,48,PBUF_RAM);uint8_t *bytes=p->payload;bytes[0]=0x24;bytes[1]=2;uint32_t stamp=htonl((uint32_t)(1704153600UL-2085978496UL));memcpy(bytes+40,&stamp,4);ip_addr_t address={0x1234};sntp_recv(NULL,sntp_pcb,p,&address,123);core_end();assert(callbacks==1&&wall_epoch==1704153600);assert(sntp_get_sync_status()==SNTP_SYNC_STATUS_COMPLETED);assert(sntp_get_sync_status()==SNTP_SYNC_STATUS_RESET);bool hourly=false;for(unsigned i=0;i<32;i++)if(timers[i].fn==sntp_request&&timers[i].delay==61U*60000U)hourly=true;assert(hourly);}
 else if(!strcmp(test,"pcb_oom")){ready();fail_udp=1;esp_err_t result=native_time_sntp_apply(&a);
#ifndef HOST_NO_LWIP_ASSERT
  (void)result;assert(!"SDK PCB assertion unexpectedly returned");
#else
  assert(result==ESP_ERR_NO_MEM&&!sntp_enabled());fail_udp=0;assert(native_time_sntp_apply(&b)==ESP_OK);
#endif
 }
 else if(!strcmp(test,"failed_restart_dns")){ready();assert(native_time_sntp_apply(&a)==ESP_OK);run_request();unsigned entry=find_dns(a.servers[0]);fail_udp=1;assert(native_time_sntp_apply(&b)==ESP_ERR_NO_MEM);assert(!sntp_enabled());complete_dns(entry,true,0x1234);assert(null_sends==1&&timer_count()>0);fail_udp=0;assert(native_time_sntp_apply(&c)==ESP_OK);puts("KNOWN SDK limitation: late DNS after failed start can rearm timers while disabled");}
 else assert(!"unknown case");
 cleanup();printf("PASS %s\n",test);return 0;
}
